-- Dissect: Local Round Trip Classes
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.local_round_trip_classes.dissect = function(buffer, offset, size, packet, parent)
  local range = buffer(offset, size)
  local text = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.tip_text(range)
  local level, rest = text:match("^(%d+):(.*)$")
  if level == nil then
    parent:add_tvb_expert_info(nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.experts.invalid_value, range, "Local Round Trip Classes: indexed value without a level: "..text)
    return
  end
  text = rest
  local value = tonumber(text)
  if value == nil then
    parent:add_tvb_expert_info(nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.experts.invalid_value, range, "Local Round Trip Classes: not a number: "..text)
    return
  end
  value = Int64.new(value)
  local display = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.local_round_trip_classes.display(text, level)
  local item = parent:add(omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.fields.local_round_trip_classes, range, value, display)
  item:add(omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.fields.tip_level, range, tonumber(level))
  return item, text
end

