-- Sequenced Data Packet: a tip message, dispatched on its type token
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.sequenced_data_packet = {}

-- Read runtime size of: Sequenced Data Packet
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.sequenced_data_packet.size = function(buffer, offset)
  local index = offset

  -- Dependency element: Packet Length
  local packet_length = buffer(offset - 3, 2):uint()

  return packet_length - 1
end

-- Dissect runtime sized group: Sequenced Data Packet, as a tip message
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.sequenced_data_packet.dissect = function(buffer, offset, packet, parent)
  local size = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.sequenced_data_packet.size(buffer, offset)
  local tokens = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.tip_tokens(buffer, offset, size)
  if #tokens == 0 then
    return offset + size
  end

  local type = buffer(tokens[1].offset, tokens[1].length):string()
  local message = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.messages[type]
  if message == nil then
    local item = parent:add(omi_nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.fields.sequenced_data_packet, buffer(offset, size))
    item:add_proto_expert_info(nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.experts.unknown_message, "Unknown tip message type: "..type)
  else
    message.dissect(buffer, offset, size, packet, parent, tokens)
  end
  packet.cols.info:append(type.." ")

  return offset + size, type
end

