-- Remaining Bytes For: Server Soup Bin Tcp Packet
local server_soup_bin_tcp_packet_bytes_remaining = function(buffer, index, available)
  -- Calculate the number of bytes remaining
  local remaining = available - index

  -- Check if packet size can be read
  if remaining < nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_packet_header.size then
    return -DESEGMENT_ONE_MORE_SEGMENT
  end

  -- Parse runtime size
  local current = buffer(index, 2):uint() + 2

  -- Check if enough bytes remain
  if remaining < current then
    return -(current - remaining)
  end

  return remaining, current
end

-- Server Packet
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_packet = {}

-- Verify required size of Tcp packet
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_packet.requiredsize = function(buffer)
  return buffer:len() >= nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_packet_header.size
end

-- Dissect Server Packet
nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_packet.dissect = function(buffer, packet, parent)
  -- establish frame context from the conversation's stored values
  local data = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.conversation.data(packet)
  if not packet.visited then
    data.accepted_sequence_number.frames[packet.number] = data.accepted_sequence_number.last
  end
  nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.accepted_sequence_number.current = data.accepted_sequence_number.frames[packet.number]
  nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.conversation.current = data

  local index = 0

  -- Dependency for Server Soup Bin Tcp Packet
  local end_of_payload = buffer:len()

  -- Server Soup Bin Tcp Packet: Struct of 2 fields
  while index < end_of_payload do

    -- Are minimum number of bytes are available?
    local available, size_of_server_soup_bin_tcp_packet = server_soup_bin_tcp_packet_bytes_remaining(buffer, index, end_of_payload)

    if available > 0 then
      index = nasdaq_nordicmarkets_consolidatedfeed_tip_v3_10_17_1.server_soup_bin_tcp_packet.dissect(buffer, index, packet, parent, size_of_server_soup_bin_tcp_packet)
    else
      -- More bytes needed, so set packet information
      packet.desegment_offset = index
      packet.desegment_len = -(available)

      -- Claim the whole buffer: tcp keeps the bytes from desegment_offset for reassembly
      return end_of_payload
    end
  end

  return index
end

